import{_ as i,o as s,c as t,ah as a}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Heliodor Linux Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/heliodor.md","filePath":"benchmarks/heliodor.md"}'),n={name:"benchmarks/heliodor.md"};function o(r,e,l,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="heliodor-linux-benchmark" tabindex="-1">Heliodor Linux Benchmark <a class="header-anchor" href="#heliodor-linux-benchmark" aria-label="Permalink to &quot;Heliodor Linux Benchmark&quot;">​</a></h1><p>Heliodor is Celox&#39;s large external Veryl workload. It boots a pinned Linux image and compares Celox&#39;s native and tiered JIT backends with synchronous and tiered Veryl-CC using the same design revision and input workload on each architecture. Celox tiered starts on the interpreter while native code is generated in the background. On x86-64 it first adopts a baseline native image, then replaces it with the optimizing image at a safe point, preserving live state and event buffers. Code-generation tracing uses the optimizing pipeline directly. Veryl-CC tiered starts on Cranelift and switches to C code as its background compilation completes, matching <code>veryl test --backend cc</code>&#39;s default <code>aot_c_async=true</code> setting. The synchronous Veryl-CC runner explicitly sets <code>aot_c_async=false</code> and waits for C compilation before simulation. Standalone Cranelift Linux boot measurements are not collected or published because their runtime is outside the useful scale of this comparison.</p><h2 id="what-the-benchmark-answers" tabindex="-1">What the benchmark answers <a class="header-anchor" href="#what-the-benchmark-answers" aria-label="Permalink to &quot;What the benchmark answers&quot;">​</a></h2><p>The benchmark separates three questions:</p><ol><li>How long do the synchronous backends take to compile the design?</li><li>How long does the complete workload take to execute, including the testbench?</li><li>How long does tiered execution take from startup through Linux completion while compilation overlaps simulation?</li></ol><p>Execution time includes the testbench for both simulators. Tiered results have separate charts for startup until simulation begins, execution with background compilation, and total time through Linux completion. The tiered execution interval includes time on the initial backend and must not be read as compiled-code throughput. Veryl-CC may finish on Cranelift before C compilation completes; these runs remain valid tiered measurements. Startup and total time begin before design analysis; source-file loading and building the benchmark executables with Cargo are excluded. The TSV retains <code>compile_elapsed_ns</code> for tiered startup, not the total background compiler time. Each synchronous and tiered Veryl-CC run uses its own empty AOT-C cache. A partial boot, projected completion time, or compile-only result is not a successful execution result.</p><h2 id="valid-result" tabindex="-1">Valid result <a class="header-anchor" href="#valid-result" aria-label="Permalink to &quot;Valid result&quot;">​</a></h2><p>A run is accepted only when it:</p><ul><li>uses the pinned Heliodor and workload revisions;</li><li>reaches the configured Linux completion marker;</li><li>records compilation and execution separately;</li><li>compares runners built from the intended Celox and Veryl revisions;</li><li>preserves the logs needed to diagnose a timeout or semantic mismatch;</li><li>proves that Celox tiered promoted and executed at least one generated-code evaluation before Linux completed;</li><li>confirms that Veryl-CC tiered enabled asynchronous C compilation and executed at least one compiled or fallback dispatch.</li></ul><p>This fixed completion marker prevents faster failures or incomplete boots from being reported as performance improvements.</p><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>To compare both tiered backends:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;celox-tiered veryl-cc-tiered&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>For repeated local profiling of generated native code, enable the build cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">celox</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_CELOX_BUILD_CACHE_DIR=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/target/heliodor/build-cache&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>The runner also accepts <code>--build-cache-dir DIR</code> directly. A hit skips frontend analysis, optimization, and native code generation; each run initializes fresh simulation state. <code>CELOX_BUILD_CACHE</code> logs <code>status=hit</code> or <code>status=miss</code>. Source contents and order, project metadata and dependency mappings, test name, optimization/pass settings, four-state mode, native memory width, SLP settings, diagnostics, detected x86 CPU/OS capabilities, working directory relative to the project root, and the exact runner executable identify the compilation. Files consulted by <code>$readmemh</code>, including absent lookup candidates, are checked by content before reuse. Dependency namespaces and properties are resolved before cache lookup. Component Cargo metadata, manifest candidates, and prebuilt WASM files are also checked, including manifest modification times that determine which interface takes precedence. Native component library presence, including Cargo <code>[lib].name</code> overrides, is tracked so adding or removing a library refreshes the runtime library selection. Keep build inputs stable during compilation.</p><p>Cache dependency paths and image library, file-base, and source-location paths are stored relative to the project root. On load they are bound to the current root. For an explicitly absolute <code>$readmemh</code> path, a hash of its physical location also prevents a relocated file from replacing the design&#39;s fixed reference. Moving a project preserves cache reuse when its inputs and relative working directory stay equivalent. The key also includes each source&#39;s resolved namespace. External paths use <code>..</code>; paths on a different Windows drive cannot be represented and bypass caching. CLI native image exports use the same relative paths and fail before writing if a path cannot be represented relative to the project root. <code>--native-image-input</code> binds them using the current <code>--project</code> root without loading source files. Existing images with absolute paths remain loadable. Design-authored strings are preserved; the cache still contains compiled design data and is not an anonymized artifact. Earlier cache entries are not reused by the new relative-path format.</p><p>Caching is opt-in and supports the native backend, including host codegen in <code>host-qemu</code> mode and <code>--compile-only --native-image-output</code>. It cannot be combined with <code>--native-image-input</code> or <code>--dump-ir-dir</code>. Cache directories contain executable code and must be trusted local directories. Writes are atomic; invalid entries or cache I/O failures fall back to compilation. Delete the directory to clear it; entries are not evicted automatically.</p><p>On a hit, <code>compile_ns</code> measures loading and initialization rather than compilation. Use cached runs to study execution, and disable caching when comparing build or end-to-end performance. The fixed CI <code>gate</code> always disables this cache.</p><p>The fixed CI <code>gate</code> runs <code>veryl-cc-sync</code>, <code>celox</code>, <code>celox-tiered</code>, and <code>veryl-cc-tiered</code> on x86-64. The nightly AArch64 job measures the same four backends. All pinned jobs use <code>scripts/heliodor-revision</code>. Each successful suite backend publishes immediately, without waiting for other backends, workloads, or architectures. Failed runs remain failures in CI.</p><p>The first run needs network access to obtain the pinned Heliodor checkout. The script prints the selected revisions, build configuration, completion status, and timings. Use the same machine and configuration for before/after comparisons.</p><p>Published results appear in the <strong>Heliodor Linux</strong> section of the <a href="./">benchmark dashboard</a>.</p><h2 id="expanded-linux-suite" tabindex="-1">Expanded Linux suite <a class="header-anchor" href="#expanded-linux-suite" aria-label="Permalink to &quot;Expanded Linux suite&quot;">​</a></h2><p>Nightly and non-profiling manual runs also measure the following workloads on x86-64 (<code>ubuntu-24.04</code>) and AArch64 (<code>ubuntu-24.04-arm</code>), using all four backends:</p><table tabindex="0"><thead><tr><th>Guest Linux kernel</th><th>Hart counts</th></tr></thead><tbody><tr><td>5.15</td><td>1, 2, 4, 8</td></tr><tr><td>6.6</td><td>1, 2, 4</td></tr><tr><td>7.1</td><td>1</td></tr><tr><td>7.1 with vector enabled</td><td>1</td></tr></tbody></table><p>These 9 workloads use Heliodor revision <code>6285682fa0a514077da9d17fee385c7841160025</code>. Kernel versions refer to the simulated guest, not the benchmark host OS. Backends execute sequentially on the same VM within each group below (36 jobs for the complete suite):</p><table tabindex="0"><thead><tr><th>Workload</th><th>Comparison groups per architecture</th></tr></thead><tbody><tr><td>1/2 harts, or x86-64 4 harts</td><td>All four backends in one job</td></tr><tr><td>AArch64 4 harts</td><td>Two jobs: Celox native + Veryl-CC sync; Celox tiered + Veryl-CC tiered</td></tr><tr><td>8 harts, either architecture</td><td>Four jobs, one per backend</td></tr><tr><td>Every SMP workload (2, 4, 8 harts)</td><td>One more job: <code>celox-parallel</code></td></tr></tbody></table><p><code>celox-parallel</code> is the native backend with <a href="./../guide/parallel-simulation.html">multi-threaded simulation</a>, using one thread per host vCPU (<code>HELIODOR_CELOX_THREADS</code>, default <code>nproc</code>). Its own job keeps the comparison groups&#39; time budgets unchanged. The dashboard shows it as &quot;multi-threaded&quot; next to single-threaded native execution.</p><p>Recent complete eight-hart runs total 10–13 hours on x86-64 and 17–18 hours on AArch64. AArch64 four-hart runs total 5–7 hours, so splitting them into equivalent execution modes preserves useful same-CPU comparisons with time for builds. Different groups may use different CPUs. CPU and host identity are retained in each artifact. Each successful backend publishes independently. Each runner has a one-hour timeout for 1/2 harts, three hours for 4 harts, and five and a half hours for 8 harts; timeouts and incomplete runs fail the job and are not published as timings. The suite applies testbench adjustment <code>8hart-100m-v1</code>: the 8-hart Veryl test gets the same 100-million-cycle budget as its upstream Verilator wrapper, replacing the stale 30-million-cycle limit. The shutdown assertion is unchanged. <code>HELIODOR_SUITE=1</code> applies this adjustment only to the pinned suite revision; the selected adjustment is recorded in the job log. Switching the same checkout back to <code>HELIODOR_SUITE=0</code> restores the stock testbench. Additional local edits to a patched wrapper are preserved and reported as an error.</p><p>Linux 7.1 SMP (2/4 harts) is excluded pending an upstream RTL fix. Both configurations stop retiring instructions on one hart; the two-hart case also reproduces on Verilator, with a stalled data-cache read and another hart waiting for a lock. These failures are not counted as successful benchmark results.</p><p>The separate HEAD compatibility job skips only upstream revision <code>94e9c5821c24a8941c3ddc3b76daddc7124a855a</code>: its testbench lacks the <code>initial_assign</code> annotations for ROM/DRAM preloads added by <code>6285682</code>. CI records this as a known-source exclusion, not a successful simulation. Every other upstream HEAD remains eligible for the compatibility test.</p><p>The dashboard shows the current suite, with each kernel and hart count labeled separately. Each chart uses the compilation, execution, and tiered timing definitions described above. These large jobs do not run on pull requests.</p><p>For example, to run the Linux 6.6 four-hart workload locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_REF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">6285682fa0a514077da9d17fee385c7841160025</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TESTS=test_soc_66_smp_linux_boot_4hart </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;veryl-cc-sync celox celox-tiered veryl-cc-tiered&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_CELOX_CARGO_PROFILE=release </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">HELIODOR_TIMEOUT_SEC=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10800</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>For a focused manual rerun, set <code>suite_test</code>, <code>suite_runner</code>, and/or <code>suite_arch</code> in the workflow dispatch inputs. Empty inputs select the complete suite. Filtered runs skip the gate. Successful results from manual runs on <code>master</code> publish individually; runs on other branches do not publish. For example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> heliodor-bench.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_test=test_soc_66_smp_linux_boot_4hart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_runner=celox</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_arch=aarch64</span></span></code></pre></div><p>Nightly and manual runs use the same grouping above. To compare a subset, give <code>suite_runner</code> a space-separated list; this narrows the groups without combining them. Backends execute in the supplied order within each group. CPU, runner, group, run/attempt, and boot identifiers are saved with the results. Every Veryl-CC run still gets a fresh AOT-C cache.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> heliodor-bench.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_test=test_soc_66_smp_linux_boot_4hart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_runner=&quot;celox-tiered veryl-cc-tiered&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite_arch=aarch64</span></span></code></pre></div><p>Each group has a shared 5-hour-50-minute budget, including building the runners. This reserves 20 minutes beyond the longest per-runner timeout for checkout and Rust builds, with about 10 minutes left for setup, termination, and artifact upload before the <a href="https://docs.github.com/en/actions/reference/limits" target="_blank" rel="noreferrer">hosted job&#39;s six-hour limit</a>. A timeout or missing backend fails CI. Completed backends still publish; incomplete boots do not publish timings. The per-backend limits above also apply within this shared budget. Separate workflow runs, including different commits, can use different CPUs; their history is not a same-host comparison.</p>`,40)])])}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
